62: function nonEmptyString(value: unknown): string | undefined {
63:   return typeof value === "string" && value.trim() ? value.trim() : undefined;
64: }
65: 
66: function boundedInteger(
67:   value: unknown,
68:   fallback: number,
69:   min: number,
70:   max: number,
71: ): number {
72:   if (typeof value === "number" && Number.isInteger(value)) {
73:     return Math.min(max, Math.max(min, value));
74:   }
75:   return fallback;
76: }
