78: function strictInteger(
79:   value: unknown,
80:   field: string,
81:   min: number,
82:   max: number,
83: ): number {
84:   if (typeof value !== "number" || !Number.isInteger(value)) {
85:     throw new Error(
86:       `Invalid OpenCode Remembering config: ${field} must be an integer`,
87:     );
88:   }
89:   if (value < min || value > max) {
90:     throw new Error(
91:       `Invalid OpenCode Remembering config: ${field} must be between ${min} and ${max}`,
92:     );
93:   }
94:   return value;
95: }
