97: /** Fail closed: an explicit schema override must be a safe SQL identifier. */
98: export function validateSchemaName(schema: string): string {
99:   if (!SCHEMA_PATTERN.test(schema) || schema.length > MAX_SCHEMA_LENGTH) {
100:     throw new Error(
101:       "Invalid OpenCode Remembering config: schema must be a PostgreSQL " +
102:         `identifier (1-${MAX_SCHEMA_LENGTH} chars, letters/digits/_/$). ` +
103:         "Refusing to substitute a global schema.",
104:     );
105:   }
106:   if (schema.toLowerCase().startsWith("pg_")) {
107:     throw new Error(
108:       "Invalid OpenCode Remembering config: schema must not use the " +
109:         "reserved pg_ prefix.",
110:     );
111:   }
112:   return schema;
113: }
