135: async function readRawConfig(): Promise<{ raw: RawConfig; path: string }> {
136:   const configPath = path.join(
137:     os.homedir(),
138:     ".config",
139:     "opencode",
140:     "remembering.json",
141:   );
142:   try {
143:     const parsed = JSON.parse(await fs.readFile(configPath, "utf8"));
144:     if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
145:       throw new Error("configuration root must be an object");
146:     }
147:     return { raw: parsed as RawConfig, path: configPath };
148:   } catch (error) {
149:     if ((error as NodeJS.ErrnoException).code === "ENOENT") {
150:       return { raw: {}, path: configPath };
151:     }
152:     throw new Error(
153:       `Invalid OpenCode Remembering config at ${configPath}: ${String(error)}`,
154:     );
155:   }
156: }
