158: function parseEmbedding(raw: RawConfig): EmbeddingConfig {
159:   const provider =
160:     nonEmptyString(process.env.REMEMBERING_EMBEDDING_PROVIDER) ??
161:     nonEmptyString(raw.embedding?.provider) ??
162:     "ollama";
163:   if (provider === "hashing") {
164:     // The hashing embedder is a deterministic test double, never a
165:     // production retrieval model. It is only honoured for explicitly
166:     // opted-in local tests, never by silent fallback.
167:     if (process.env.REMEMBERING_ALLOW_TEST_EMBEDDINGS !== "1") {
168:       throw new Error(
169:         "Invalid OpenCode Remembering config: embedding.provider " +
170:           '"hashing" is a test double and is refused without ' +
171:           "REMEMBERING_ALLOW_TEST_EMBEDDINGS=1.",
172:       );
173:     }
174:   } else if (provider !== "ollama" && provider !== "sentence-transformers") {
175:     throw new Error(
176:       `Invalid OpenCode Remembering config: embedding.provider must be ` +
177:         `"ollama", "sentence-transformers" or "hashing", got ${JSON.stringify(provider)}.`,
178:     );
179:   }
180:   const model =
181:     nonEmptyString(process.env.REMEMBERING_EMBEDDING_MODEL) ??
182:     nonEmptyString(raw.embedding?.model) ??
183:     "bge-m3";
184:   const host =
185:     nonEmptyString(process.env.REMEMBERING_EMBEDDING_HOST) ??
186:     nonEmptyString(raw.embedding?.host) ??
187:     "http://localhost:11434";
188:   return { provider, model, host };
189: }
190: 
191: function parseRetrieval(raw: RawConfig): RetrievalConfig {
192:   const mode = nonEmptyString(raw.retrieval?.mode) ?? "hybrid";
193:   if (mode !== "lexical" && mode !== "dense" && mode !== "hybrid") {
194:     throw new Error(
195:       `Invalid OpenCode Remembering config: retrieval.mode must be ` +
196:         `"lexical", "dense" or "hybrid", got ${JSON.stringify(mode)}.`,
197:     );
198:   }
199:   const reranker = nonEmptyString(raw.retrieval?.reranker) ?? "none";
200:   if (reranker !== "none" && reranker !== "overlap" && reranker !== "cross-encoder") {
201:     throw new Error(
202:       `Invalid OpenCode Remembering config: retrieval.reranker must be ` +
203:         `"none", "overlap" or "cross-encoder", got ${JSON.stringify(reranker)}.`,
204:     );
205:   }
206:   // Default reranker is "none": the engine must not download a
207:   // cross-encoder model unless the operator explicitly asks for it.
208:   return {
209:     mode,
210:     lexicalK:
211:       raw.retrieval?.lexical_k === undefined
212:         ? 30
213:         : strictInteger(raw.retrieval.lexical_k, "retrieval.lexical_k", 1, 100),
214:     denseK:
215:       raw.retrieval?.dense_k === undefined
216:         ? 30
217:         : strictInteger(raw.retrieval.dense_k, "retrieval.dense_k", 1, 100),
218:     fusionK:
219:       raw.retrieval?.fusion_k === undefined
220:         ? 60
221:         : strictInteger(raw.retrieval.fusion_k, "retrieval.fusion_k", 1, 1000),
222:     rerankK:
223:       raw.retrieval?.rerank_k === undefined
224:         ? 8
225:         : strictInteger(raw.retrieval.rerank_k, "retrieval.rerank_k", 1, 50),
226:     reranker,
227:   };
228: }
