620:     throw new Error(
621:       `Invalid remember action ${JSON.stringify(request.action)}: expected 'remember', 'correct', 'supersede' or 'retract'.`,
622:     );
623:   }
624:   if (request.role !== undefined && !REMEMBER_ROLES.includes(request.role)) {
625:     throw new Error(
626:       `Invalid remember role ${JSON.stringify(request.role)}.`,
627:     );
628:   }
629:   if (
630:     request.caller_scope !== undefined &&
631:     !request.caller_scope.trim()
