643: const LOOP_ACTIONS: LoopAction[] = ["list", "get", "history"];
644: const LOOP_STATES: LoopState[] = ["open", "completed", "cancelled", "superseded", "uncertain"];
645: 
646: function validateLoopRequest(request: LoopRequest): void {
647:   const action = request.action ?? "list";
648:   if (!LOOP_ACTIONS.includes(action)) {
649:     throw new Error(
650:       `Invalid loops action ${JSON.stringify(request.action)}: expected 'list', 'get' or 'history'.`,
651:     );
652:   }
653:   if ((action === "get" || action === "history") && !request.loop_id?.trim()) {
654:     throw new Error(`Loops action '${action}' requires loop_id.`);
655:   }
656:   if (request.state !== undefined && !LOOP_STATES.includes(request.state)) {
657:     throw new Error(
658:       `Invalid loop state ${JSON.stringify(request.state)}.`,
659:     );
660:   }
661:   if (
662:     request.limit !== undefined &&
663:     (!Number.isInteger(request.limit) || request.limit < 1)
664:   ) {
665:     throw new Error("Loops limit must be a positive integer.");
666:   }
667: }
668: 
669: function validateTraceRequest(request: TraceRequest): void {
670:   if (request.mode === "get" || request.mode === "verify") {
671:     if (!request.trace_id.trim()) {
672:       throw new Error(`Trace mode '${request.mode}' requires trace_id.`);
673:     }
674:   } else if (request.mode === "find") {
675:     const filters = request.filters ?? {};
676:     if (
677:       filters.limit !== undefined &&
678:       (!Number.isInteger(filters.limit) || filters.limit < 1)
679:     ) {
680:       throw new Error("Trace find limit must be a positive integer.");
681:     }
682:   } else if (request.mode === "explain") {
683:     if (!request.trace_id.trim() || !request.candidate_id.trim()) {
684:       throw new Error(
685:         "Trace mode 'explain' requires trace_id and candidate_id.",
686:       );
687:     }
688:   } else if (request.mode === "replay") {
689:     if (!request.trace_id.trim()) {
690:       throw new Error("Trace mode 'replay' requires trace_id.");
691:     }
692:     if (request.replay_kind !== "trust" && request.replay_kind !== "selection") {
693:       throw new Error(
694:         `Invalid replay_kind ${JSON.stringify(request.replay_kind)}.`,
695:       );
696:     }
697:   } else if (request.mode === "diff") {
698:     if (!request.trace_id.trim() || !request.diff_with.trim()) {
699:       throw new Error(
700:         "Trace mode 'diff' requires trace_id and diff_with.",
701:       );
702:     }
703:   }
704: }
