706: function validateWorkRequest(work: WorkRequest): void {
707:   const mode = work.mode ?? "auto";
708:   if (mode !== "auto" && mode !== "explicit" && mode !== "none") {
709:     throw new Error(
710:       `Invalid work mode ${JSON.stringify(work.mode)}: expected 'auto', 'explicit' or 'none'.`,
711:     );
712:   }
713:   if (mode === "explicit" && !work.work_type?.trim()) {
714:     throw new Error("Explicit work requires work_type.");
715:   }
716:   if (work.signals !== undefined && !Array.isArray(work.signals)) {
717:     throw new Error("work.signals must be a list.");
718:   }
719: }
