721: function validateTemporalRequest(temporal: TemporalStandpointRequest): void {
722:   const mode = temporal.mode ?? "current";
723:   if (mode !== "current" && mode !== "valid_at" && mode !== "as_known" && mode !== "bitemporal") {
724:     throw new Error(
725:       `Invalid temporal mode ${JSON.stringify(temporal.mode)}: expected 'current', 'valid_at', 'as_known' or 'bitemporal'.`,
726:     );
727:   }
728:   if ((mode === "valid_at" || mode === "bitemporal") && !temporal.valid_at?.trim()) {
729:     throw new Error(`Temporal mode '${mode}' requires valid_at.`);
730:   }
731:   if ((mode === "as_known" || mode === "bitemporal") && !temporal.known_at?.trim()) {
732:     throw new Error(`Temporal mode '${mode}' requires known_at.`);
733:   }
734: }
