105: /**
106:  * Native TypeScript baseline engine (Stage 2 vertical slice).
107:  * Owns its pg Pool; call close() when done.
108:  */
109: export class RememberingEngine {
110:   private pool: Pool | null = null;
111:   private embedder: EmbeddingProvider;
112:   readonly chunking: ChunkingConfig;
113: 
114:   constructor(private readonly options: EngineOptions) {
115:     assertSchemaName(options.schema);
116:     this.embedder = buildEmbedder(options.embedding);
117:     this.chunking = options.chunking ?? DEFAULT_CHUNKING;
118:   }
119: 
120:   /** Override the embedder (tests / differential harness). */
121:   withEmbedder(embedder: EmbeddingProvider): this {
122:     this.embedder = embedder;
123:     return this;
124:   }
125: 
126:   private async poolConnected(): Promise<Pool> {
127:     if (!this.pool) this.pool = await connectPool(this.options.dsn);
128:     return this.pool;
129:   }
130: 
131:   async close(): Promise<void> {
132:     if (this.pool) {
133:       await this.pool.end().catch(() => {});
134:       this.pool = null;
135:     }
136:   }
137: 
138:   private store(pool: Pool): BaselineStore {
139:     return new BaselineStore(pool, this.options.dsn, this.options.schema);
140:   }
141: 
142:   async doctor(): Promise<Record<string, unknown>> {
143:     const pool = await this.poolConnected();
144:     const baseline = await doctorBaseline(pool, {
145:       dsn: this.options.dsn,
146:       schema: this.options.schema,
147:       projectDirectory: this.options.projectDirectory,
148:       embedding: this.options.embedding,
149:     });
150:     return { ...baseline, native: true };
151:   }
152: 
153:   async setup(): Promise<{ ok: boolean; schema: string; embedding: { provider: string; model: string; dimension: number; version: string } }> {
154:     const pool = await this.poolConnected();
155:     const client = await pool.connect();
156:     try {
157:       await ensureExtension(client, "vector");
158:       await ensureExtension(client, "pg_trgm");
159:     } finally {
160:       client.release();
161:     }
162:     const probe = await this.embedder.embed(["dimension probe"]);
163:     const dimension = probe.dimension;
164:     const store = this.store(pool);
165:     await store.initialise(dimension);
166:     await this.ensureProjectMeta(pool);
167:     await store.ensureHnsw();
168:     // Stage 3 subsystem stores (idempotent; no data migration).
169:     await new PostgresTemporalStore(pool, this.options.schema).initialise();
170:     await new PostgresStandingStore(pool, this.options.schema).initialise();
171:     await new PostgresTraceStore(pool, this.options.schema).initialise();
172:     await new PostgresLoopStore(pool, this.options.schema).initialise();
173:     await new PostgresWriteStore(pool, this.options.schema).initialise();
174:     const { error: trustError } = await loadTrustPolicy(this.options.projectDirectory);
175:     if (trustError) throw new EngineError("TRUST_POLICY_INVALID", trustError);
176:     const { valid: writeValid, error: writeError } = await loadWritePolicy(this.options.projectDirectory);
177:     if (!writeValid && writeError) throw new EngineError("WRITE_POLICY_INVALID", writeError);
178:     return {
179:       ok: true,
180:       schema: this.options.schema,
181:       embedding: {
182:         provider: probe.provider,
183:         model: probe.model,
184:         dimension: probe.dimension,
185:         version: `${probe.provider}:${probe.model}:${probe.dimension}`,
186:       },
187:     };
188:   }
189: 
190:   private async ensureProjectMeta(pool: Pool): Promise<void> {
191:     const canonical = await canonicalProjectDir(this.options.projectDirectory);
192:     const client = await pool.connect();
193:     try {
194:       const meta = await readProjectMeta(client, this.options.schema);
195:       const recorded = meta["project.path"];
196:       if (recorded != null && recorded !== canonical) {
197:         throw new EngineError(
198:           "SCHEMA_MISMATCH",
199:           `schema ${JSON.stringify(this.options.schema)} is already claimed by project ${JSON.stringify(recorded)}, but this project resolves to ${JSON.stringify(canonical)}. Refusing to mix projects: fix the schema configuration instead of sharing an index.`,
200:         );
201:       }
202:       const stamp = new Date().toISOString();
203:       const s = ident(this.options.schema);
204:       for (const [key, value] of [
205:         ["project.path", canonical],
206:         ["project.schema", this.options.schema],
207:         ["project.recorded_at", stamp],
208:       ] as Array<[string, string]>) {
209:         await client.query(
210:           `INSERT INTO ${s}.meta (key, value) VALUES ($1, $2) ON CONFLICT (key) DO NOTHING`,
211:           [key, value],
212:         );
213:       }
214:     } finally {
215:       client.release();
216:     }
217:   }
218: 
219:   async refresh(): Promise<RefreshReport> {
220:     const pool = await this.poolConnected();
221:     const store = this.store(pool);
222:     // Baseline refresh requires an initialised store.
223:     const probe = await this.embedder.embed(["dimension probe"]);
224:     await store.initialise(probe.dimension);
225:     await this.ensureProjectMeta(pool);
226: 
227:     const report: RefreshReport = {
228:       ok: true,
229:       schema: this.options.schema,
230:       discovered: 0,
231:       indexed: 0,
232:       unchanged: 0,
233:       added: 0,
234:       changed: 0,
235:       removed: 0,
236:       chunks: 0,
237:       embedded: 0,
238:       failed: [],
239:     };
240:     const { realpath } = await import("node:fs/promises");
241:     let root: string;
242:     try {
243:       root = await realpath(this.options.projectDirectory);
244:     } catch {
245:       const { resolve } = await import("node:path");
246:       root = resolve(this.options.projectDirectory);
247:     }
248:     const paths = await discover(root);
249:     report.discovered = paths.length;
250:     const known = await store.knownSources();
251:     const seen = new Set<string>();
252:     const version = await this.embeddingVersion();
253:     for (const fullPath of paths) {
254:       const source = await parseFile(fullPath, root);
255:       if (!source) {
256:         const { basename } = await import("node:path");
257:         report.failed.push(basename(fullPath));
258:         continue;
259:       }
260:       seen.add(source.sourceId);
261:       if (known[source.sourceId] === source.contentHash) {
262:         report.unchanged += 1;
263:         continue;
264:       }
265:       const isNew = !(source.sourceId in known);
266:       await store.upsertSource(source.sourceId, source.artifactType, source.contentHash, source.timestamp);
267:       const chunks = chunkSource(source, this.chunking);
268:       const texts = chunks.map((c) => c.text);
269:       const vectors = texts.length ? (await this.embedder.embed(texts)).vectors : [];
270:       const rows = chunks.map((c, i) => ({
271:         chunkId: c.chunkId,
272:         sourceId: c.sourceId,
273:         ordinal: c.ordinal,
274:         text: c.text,
275:         section: c.section,
276:         charStart: c.charStart,
277:         charEnd: c.charEnd,
278:         contentHash: c.contentHash,
279:         chunker: `${this.chunking.policy}:${this.chunking.chunkerVersion}`,
280:         embeddingVersion: version,
281:         embedding: vectors[i] ?? [],
282:       }));
283:       await store.replaceChunks(source.sourceId, rows);
284:       report.chunks += rows.length;
285:       report.embedded += rows.length;
286:       report.indexed += 1;
287:       if (isNew) report.added += 1;
288:       else report.changed += 1;
289:     }
290:     for (const sourceId of Object.keys(known).sort()) {
291:       if (seen.has(sourceId)) continue;
292:       // Explicit-memory sources are managed by the write subsystem,
293:       // not by repository discovery: refresh must never prune them.
294:       if (sourceId.startsWith("memory://")) continue;
295:       await store.removeSource(sourceId);
296:       report.removed += 1;
297:     }
298:     await store.ensureHnsw();
299:     await this.verifyWith(store);
300:     const temporal = await this.temporalImportSafe();
301:     const report2 = report as RefreshReport & { temporal?: { imported: number; duplicates: number; failed: string[]; events: number; subjects: string[] }; message?: string };
302:     report2.temporal = {
303:       imported: temporal.imported,
304:       duplicates: temporal.duplicates,
305:       failed: temporal.failed,
306:       events: temporal.events,
307:       subjects: temporal.subjects,
308:     };
309:     if (temporal.failed.length > 0) {
310:       report2.message = `temporal import failures: ${temporal.failed.join("; ")}`;
311:     }
312:     // Standing / loop / explicit-memory file imports run on every refresh so
313:     // checked-in event files converge without a separate manual step.
314:     // Failures are recorded, never thrown: refresh must not fail because an
315:     // optional event file has a bad line.
316:     try {
317:       await this.trustImport();
318:     } catch {
319:       /* recorded in trust health */
320:     }
321:     try {
322:       await this.loopImport();
323:     } catch {
324:       /* recorded in loops health */
325:     }
326:     try {
327:       await this.memoryImport();
328:     } catch {
329:       /* recorded in writes health */
330:     }
331:     return report;
332:   }
333: 
334:   private async temporalImportSafe(): Promise<{ imported: number; duplicates: number; failed: string[]; events: number; subjects: string[] }> {
335:     try {
336:       const pool = await this.poolConnected();
337:       const pgStore = new PostgresTemporalStore(pool, this.options.schema);
338:       await pgStore.initialise();
339:       const { TemporalService: Service } = await import("./temporal/service");
340:       const summary = await new Service(pgStore).importFile(this.options.projectDirectory);
341:       return summary;
342:     } catch {
343:       return { imported: 0, duplicates: 0, failed: [], events: 0, subjects: [] };
344:     }
345:   }
346: 
347:   private async embeddingVersion(): Promise<string> {
348:     // Version without dimension probe side effects: derive from spec.
349:     // The stored per-chunk version is provider:model:dimension after first embed.
350:     const probe = await this.embedder.embed(["dimension probe"]);
351:     return `${probe.provider}:${probe.model}:${probe.dimension}`;
352:   }
