359:   private async verifyWith(store: BaselineStore): Promise<void> {
360:     if (await store.orphanChunks()) {
361:       throw new EngineError("VERIFY_FAILED", "orphan chunks remain after refresh");
362:     }
363:     const versions = await store.embeddingVersions();
364:     if (versions.length > 1) {
365:       throw new EngineError(
366:         "VERIFY_FAILED",
367:         `mixed embedding versions in store: ${JSON.stringify(versions.sort())}`,
368:       );
369:     }
370:   }
