454:       schema: this.options.schema,
455:       message: summary.failed.length
456:         ? `temporal import failures: ${summary.failed.join("; ")}`
457:         : `temporal events +${summary.imported} (${summary.events} total).`,
458:       ...summary,
459:     };
460:   }
