462:   async state(subject: string, options: { query?: string; route?: RouteRequest; temporal?: { mode?: string; valid_at?: string; known_at?: string } } = {}): Promise<Record<string, unknown>> {
463:     if (!subject.trim()) throw new EngineError("TEMPORAL_EVENT_INVALID", "subject is required.");
464:     const route = resolveRoute(options.query ?? "", options.route ?? "auto");
465:     const standpoint = validateStandpoint({
466:       mode: options.temporal?.mode ?? "current",
467:       valid_at: options.temporal?.valid_at,
468:       known_at: options.temporal?.known_at,
469:     });
470:     const pool = await this.poolConnected();
471:     const pgStore = new PostgresTemporalStore(pool, this.options.schema);
472:     await pgStore.initialise();
473:     const events = await pgStore.list();
474:     const resolved = resolveAtStandpoint(events, subject, standpoint);
475:     const versions = await pgStore.versions();
476:     return {
477:       ok: true,
478:       schema: this.options.schema,
479:       subject,
480:       value: resolved.value,
481:       status: resolved.status,
482:       detail: resolved.reason,
483:       provenance: resolved.provenance,
484:       standpoint: { mode: standpoint.mode, valid_at: standpoint.validAt ?? null, known_at: standpoint.knownAt ?? null },
485:       trajectory: resolved.trajectory,
486:       trajectory_truncated: false,
487:       incomplete_history: resolved.incompleteHistory,
488:       reason: resolved.reason,
489:       route: { route: route.route, route_source: route.routeSource, route_reason: route.routeReason, route_ambiguous: route.routeAmbiguous },
490:       store_version: versions.storeVersion,
491:       event_schema_version: versions.eventSchemaVersion,
492:       reducer_version: TEMPORAL_REDUCER_VERSION,
493:     };
494:   }
