637:   async remember(input: WriteInput): Promise<Record<string, unknown>> {
638:     const pool = await this.poolConnected();
639:     const pgStore = new PostgresWriteStore(pool, this.options.schema);
640:     await pgStore.initialise();
641:     const policy = await this.writePolicy();
642:     const service = new WriteService(pgStore, policy, () => new Date().toISOString(), async (record) => {
643:       await this.indexExplicitRecord(pool, record);
644:     });
645:     const out = await service.execute(input);
646:     if (!out.ok) return { ...out, schema: this.options.schema };
647:     const indexed = out.record ? { indexed: true, chunks: 1, embedded: 1 } : undefined;
648:     return { ...out, record_id: out.recordId, target_record_id: out.targetRecordId, action_id: out.actionId, index: indexed, schema: this.options.schema };
649:   }
