695:   async context(
696:     query: string,
697:     maxChars: number,
698:     maxResults: number,
699:     routeRequest: RouteRequest = "auto",
700:     temporal?: { mode?: string; valid_at?: string; known_at?: string },
701:     work?: { mode?: string; work_type?: string; objective?: string; prior_work_type?: string; signals?: Array<{ signal_id?: string; kind?: string; text?: string; observed_at?: string }> },
702:     trust?: { caller_scope?: string; level?: TrustLevel },
703:     selection?: { mode?: "decisive" | "full" },
704:   ): Promise<Record<string, unknown>> {
705:     const trimmed = query.trim();
706:     const route = resolveRoute(trimmed, routeRequest);
707:     const standpoint = validateStandpoint({
708:       mode: temporal?.mode ?? "current",
709:       valid_at: temporal?.valid_at,
710:       known_at: temporal?.known_at,
711:     });
712:     const search = await this.search(trimmed || "test", maxResults);
713:     const { loadProjectFrame } = await import("./frame/service");
714:     const { frame, error: frameError } = await loadProjectFrame(this.options.projectDirectory);
715:     const frameResult = establishFrame(frame, frameError, work ?? {});
716:     const pool = await this.poolConnected();
717:     const { policy: trustPolicy, valid: trustValid, error: trustError } = await loadTrustPolicy(this.options.projectDirectory);
718:     if (!trustValid) throw new EngineError("TRUST_POLICY_INVALID", trustError ?? "invalid trust policy.");
719:     const standingStore = new PostgresStandingStore(pool, this.options.schema);
720:     await standingStore.initialise();
721:     const standing = resolveStanding(await standingStore.list());
722:     const requiredLevel = trust?.level ?? "FULL";
723:     const candidates = (search.items ?? []).map((item) => ({
724:       candidateId: item.chunk_id,
725:       sourceId: item.source_id,
726:       text: item.text,
727:       section: item.section,
728:       score: item.score,
729:       provenance: `retrieval:${item.stage}`,
730:       lexicalRank: item.lexical_rank,
731:       denseRank: item.dense_rank,
732:     }));
733:     const staged = runPipelineStages(candidates, {
734:       query: trimmed,
735:       route,
736:       standpoint,
737:       frame: frameResult,
738:       trustPolicy,
739:       standing,
740:       requiredLevel,
741:       selectionMode: selection?.mode ?? "decisive",
742:       budget: { maxChars, maxResults },
743:     });
744:     const traceService = new TraceService(new PostgresTraceStore(pool, this.options.schema));
745:     await new PostgresTraceStore(pool, this.options.schema).initialise();
746:     const traceRecord = await traceService.create({
747:       query: trimmed,
748:       route: route.route,
749:       workType: frameResult.establishment?.workType ?? null,
750:       candidates: candidates.map((c) => {
751:         const stage = staged.stageMap[c.candidateId];
752:         return {
753:           candidateId: c.candidateId,
754:           sourceId: c.sourceId,
755:           text: c.text,
756:           score: c.score,
757:           stages: stage?.stages ?? { retrieved: { admitted: true, reason: "retrieved." } },
758:           terminalStage: stage?.terminalStage ?? "retrieved",
759:         };
760:       }),
761:       policies: {
762:         retrieval: `${this.options.retrieval.mode}:${this.options.retrieval.reranker}`,
763:         temporal: standpoint.mode,
764:         frame: frameResult.applied ? "framing-engine-v0.1" : "none",
765:         trust: trustPolicy.version,
766:         trustDigest: trustPolicy.digest,
767:         selection: selection?.mode ?? "decisive",
768:       },
769:       budget: { maxChars, maxResults },
770:     });
771:     const items = staged.selection.selected.map((s, i) => {
772:       const full = candidates.find((c) => c.candidateId === s.candidateId);
773:       return {
774:         chunk_id: s.candidateId,
775:         source_id: s.sourceId,
776:         section: full?.section ?? null,
777:         rank: i + 1,
778:         score: s.score,
779:         text: s.text,
780:         lexical_rank: full?.lexicalRank ?? null,
781:         dense_rank: full?.denseRank ?? null,
782:         stage: "selected",
783:       };
784:     });
785:     return {
786:       ok: true,
787:       indexed: search.indexed,
788:       schema: this.options.schema,
789:       items,
790:       trace: search.trace,
791:       trace_id: traceRecord.traceId,
792:       content: staged.content,
793:       chars: staged.chars,
794:       route: { route: route.route, route_source: route.routeSource, route_reason: route.routeReason, route_ambiguous: route.routeAmbiguous },
795:       temporal: { mode: standpoint.mode, valid_at: standpoint.validAt ?? null, known_at: standpoint.knownAt ?? null },
796:       frame: {
797:         applied: frameResult.applied,
798:         reason: frameResult.reason,
799:         control: frameResult.control,
800:         control_reason: frameResult.controlReason,
801:         establishment: frameResult.establishment ? {
802:           establishment: frameResult.establishment.establishment,
803:           work_type: frameResult.establishment.workType,
804:           objective: frameResult.establishment.objective,
805:           supporting_refs: frameResult.establishment.supportingRefs,
806:           conflicting_refs: frameResult.establishment.conflictingRefs,
807:           reasons: frameResult.establishment.reasons,
808:           source: frameResult.establishment.source,
809:           prior_work_type: frameResult.establishment.priorWorkType,
810:         } : undefined,
811:         project_frame_version: frameResult.projectFrameVersion,
812:         project_frame_digest: frameResult.projectFrameDigest,
813:       },
814:       trust: {
815:         mode: route.route,
816:         level: requiredLevel,
817:         policy_version: trustPolicy.version,
818:         policy_source: trustPolicy.source,
819:         admitted: staged.trustSummary.admitted,
820:         denied: staged.trustSummary.denied,
821:         quarantined: staged.trustSummary.quarantined,
822:       },
823:       selection: {
824:         policy_version: SELECT_POLICY_VERSION,
825:         input_count: staged.selection.summary.inputCount,
826:         selected_count: staged.selection.summary.selectedCount,
827:         dropped_redundant: staged.selection.summary.droppedRedundant,
828:         dropped_low_value: staged.selection.summary.droppedLowValue,
829:         dropped_budget: staged.selection.summary.droppedBudget,
830:         chars_before: staged.selection.summary.charsBefore,
831:         chars_after: staged.selection.summary.charsAfter,
832:         compression_ratio: staged.selection.summary.compressionRatio,
833:         budget_insufficient: staged.selection.summary.budgetInsufficient,
834:       },
835:       trace_persisted: true,
836:       admission_note: staged.admissionNote,
837:     };
838:   }
