1018:   private async importJsonLines(
1019:     relativePath: string,
1020:     handle: (raw: unknown, lineNumber: number) => Promise<{ duplicate: boolean }>,
1021:   ): Promise<{ imported: number; duplicates: number; failed: string[] }> {
1022:     const { readFile, realpath } = await import("node:fs/promises");
1023:     const { join, resolve } = await import("node:path");
1024:     let root: string;
1025:     try {
1026:       root = await realpath(this.options.projectDirectory);
1027:     } catch {
1028:       root = resolve(this.options.projectDirectory);
1029:     }
1030:     const file = join(root, relativePath);
1031:     let content: string;
1032:     try {
1033:       content = await readFile(file, "utf8");
1034:     } catch (error) {
1035:       if ((error as NodeJS.ErrnoException).code === "ENOENT") {
1036:         return { imported: 0, duplicates: 0, failed: [] };
1037:       }
1038:       throw error;
1039:     }
1040:     let imported = 0;
1041:     let duplicates = 0;
1042:     const failed: string[] = [];
1043:     const lines = content.split("\n");
1044:     for (let i = 0; i < lines.length; i++) {
1045:       const line = lines[i] as string;
1046:       if (!line.trim()) continue;
1047:       let raw: unknown;
1048:       try {
1049:         raw = JSON.parse(line);
1050:       } catch {
1051:         failed.push(`line ${i + 1}: not JSON.`);
1052:         continue;
1053:       }
1054:       try {
1055:         const out = await handle(raw, i + 1);
1056:         if (out.duplicate) duplicates += 1;
1057:         else imported += 1;
1058:       } catch (error) {
1059:         const code = (error as { code?: string })?.code ?? "IMPORT_INVALID";
1060:         failed.push(`line ${i + 1}: ${code}.`);
1061:       }
1062:     }
1063:     return { imported, duplicates, failed };
1064:   }
1065: 
1066:   async trustImport(): Promise<{ ok: boolean; schema: string; message: string; imported: number; duplicates: number; failed: string[]; events: number; subjects: string[] }> {
1067:     const pool = await this.poolConnected();
1068:     const pgStore = new PostgresStandingStore(pool, this.options.schema);
1069:     await pgStore.initialise();
1070:     const outcome = await this.importJsonLines(joinTrustEvents(), async (raw) => pgStore.append(validateStandingEvent(raw)));
1071:     const events = await pgStore.count();
1072:     return {
1073:       ok: outcome.failed.length === 0,
1074:       schema: this.options.schema,
1075:       message: outcome.failed.length ? `standing import failures: ${outcome.failed.join("; ")}` : `standing events +${outcome.imported} (${events} total).`,
1076:       ...outcome,
1077:       events,
1078:       subjects: [],
1079:     };
1080:   }
