49: /** Redact credentials from a DSN for display. The user and host stay visible. */
50: export function redactDsn(value: string): string {
51:   const schemeSplit = value.split("://");
52:   if (schemeSplit.length < 2) return value;
53:   const scheme = schemeSplit[0];
54:   const rest = schemeSplit.slice(1).join("://");
55:   const at = rest.lastIndexOf("@");
56:   if (at === -1) return value;
57:   const authority = rest.slice(0, at);
58:   const suffix = rest.slice(at + 1);
